&lt;hr&gt;
&lt;h3 class=&quot;_9k2iva0 p8i6j0c _1ibi0s314 heading3 _9k2iva1&quot;&gt;Location for this opportunity&lt;/h3&gt;
&lt;ul class=&quot;p8i6j07 p8i6j02&quot;&gt;
&lt;li class=&quot;p8i6j0a&quot;&gt;&lt;strong&gt;Office base:&lt;/strong&gt; Miami, United States
&lt;div class=&quot;tk0j8o1 _1ibi0s31a _1ibi0s3do&quot;&gt;&lt;span id=&quot;base-ui-:r1di:&quot; class=&quot;wdbi343 wdbi341 _1ibi0s3dd&quot; data-label=&quot;3 sources&quot; data-base-ui-click-trigger=&quot;&quot;&gt;&lt;/span&gt;&lt;/div&gt;
